// Disposable graphite master/detail prototype. State intentionally lives only in memory.
const initial=()=>({signed:true,name:'Jordan Morgan',role:'Member',email:'jordan@example.test',notifications:true,objectives:[{title:'Help devotional viewers find a clear next step.',description:'Build and release a clearer next-step screen for one video devotional, using AI to help write code.',status:'Draft',goals:[{text:'Test 20 viewers; count who find the next step.',target:'20 viewers',date:'Month 1'},{text:'Release after accessibility and reliability checks.',target:'Complete',date:'Month 3'},{text:'Retest 20 viewers; at least 16 find the next step.',target:'At least 16',date:'Month 6'}],notes:['Confirm viewer needs with Product before choosing the next-step wording.'],gaps:'Viewer needs unclear → Confirm with Product.',personal:'Lead technical design and AI code reviews.',leadership:'',comments:[],memberAgreed:false,leadAgreed:false,revisions:[]},{title:'Improve content discoverability across platforms.',description:'Help viewers find relevant devotional content.',status:'Draft',goals:[],notes:[],gaps:'Agree success measures with Product.',personal:'',leadership:'',comments:[],memberAgreed:false,leadAgreed:false,revisions:[]}],inbox:[{title:'Start drafting your position focus',body:'Capture the people you support, the outcome you want, and a first measurable goal. This is an illustrative notification.',read:false,target:'focus'},{title:'Casey is ready to discuss your focus',body:'Bring your draft and questions to your career lead. Review timing: ask your career lead; this prototype does not schedule reviews.',read:false,target:'review'}],members:[{name:'Jordan Morgan',role:'Member',email:'jordan@example.test'},{name:'Casey Patel',role:'Career lead',email:'casey@example.test'}]});
let state=initial(),page='focus',selected=0,guide='Example',filter='All',inboxIndex=0,memberIndex=0,query='',adding=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const obj=()=>state.objectives[selected];const btn=(label,action,cls='')=>`<button class="${cls}" onclick="${action}">${label}</button>`;const navs=[['work','✓','My work'],['focus','◎','Position focus'],['inbox','✉','Inbox'],['department','♧','Department'],['guide','▤','Guide'],['account','○','Account'],['settings','⚙','Settings']];
function toast(s){let el=document.querySelector('#toast');el.textContent=s;el.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>el.style.display='none',2800)}
function go(p){page=p;adding=false;render();window.scrollTo(0,0)}function pick(i){selected=i;render()}function change(path,value){state[path]=value}function save(){obj().revisions.unshift({title:obj().title,status:obj().status,time:new Date().toLocaleTimeString()});render();toast('Draft saved in memory.')}function reset(){state=initial();page='focus';selected=0;guide='Example';filter='All';query='';render();toast('Demo reset.')}function addObjective(){state.objectives.push({title:'New objective',description:'',status:'Draft',goals:[],notes:[],gaps:'',personal:'',leadership:'',comments:[],revisions:[],memberAgreed:false,leadAgreed:false});selected=state.objectives.length-1;page='focus';render()}function addGoal(){obj().goals.push({text:'',target:'',date:''});render()}function addNote(){const n=document.querySelector('#note').value.trim();if(!n)return toast('Write a note first.');obj().notes.unshift(n);render();toast('Note added.')}function addComment(){const n=document.querySelector('#comment').value.trim();if(!n)return toast('Write a comment first.');obj().comments.push({by:state.role==='Career lead'?'Casey Patel':'Jordan Morgan',text:n});render()}function agree(){const key=state.role==='Career lead'?'leadAgreed':'memberAgreed';obj()[key]=true;if(obj().memberAgreed&&obj().leadAgreed)obj().status='Agreed';render();toast('Agreement recorded in this demo.')}function requestReview(){obj().status='In discussion';go('review');toast('Discussion opened. No message was sent.')}function inboxPick(i){inboxIndex=i;state.inbox[i].read=true;render()}function dismiss(){state.inbox.splice(inboxIndex,1);inboxIndex=0;render()}function addMember(){state.members.push({name:'Taylor Reed',role:'Member',email:'taylor@example.test'});adding=false;memberIndex=state.members.length-1;render();toast('Taylor assigned to Engineering in memory.')}function removeMember(){state.members.splice(memberIndex,1);memberIndex=0;render();toast('Assignment removed in memory.')}function guidePick(t){guide=t;page='guide';render()}
function masters(){if(page==='focus'||page==='review'){return `<h2>My position focus</h2><p class="muted">Objectives for your current role</p><div class="tabs">${['All','Draft','Agreed'].map(f=>btn(f,`filter='${f}';render()`,f===filter?'active':'')).join('')}</div>${state.objectives.map((o,i)=>filter!=='All'&&o.status!==filter?'':`<button class="item ${i===selected?'selected':''}" onclick="pick(${i})"><small>● ${esc(o.status)}</small><strong>${esc(o.title)}</strong><small>${o.goals.length} goals · ${o.notes.length} notes　›</small></button>`).join('')}${btn('+ Add objective','addObjective()','textbtn')}`}
if(page==='guide')return `<h2>Guide</h2><p class="muted">Practical support for your growth</p>${[['Getting started','Key concepts and how to use Lantern'],['Objectives','Clarify and plan your impact'],['SMART goals','Turn objectives into clear goals'],['Example','See a position focus in practice'],['FAQ','Common questions']].map(([t,d])=>`<button class="item ${guide===t?'selected':''}" onclick="guidePick('${t}')"><strong>${t}　›</strong><small>${d}</small></button>`).join('')}`;
if(page==='inbox')return `<h2>Inbox</h2><p class="muted">Updates connected to your work</p>${state.inbox.map((n,i)=>`<button class="item ${i===inboxIndex?'selected':''}" onclick="inboxPick(${i})"><small>${n.read?'Read':'● Unread'}</small><strong>${esc(n.title)}</strong><small>Illustrative notification　›</small></button>`).join('')||'<p class="empty">You’re all caught up.</p>'}${btn('Mark all read',"state.inbox.forEach(n=>n.read=true);render()",'textbtn')}`;
if(page==='department')return `<h2>Engineering</h2><p class="muted">${state.members.length} department members</p><input class="search" placeholder="Find a member" aria-label="Find a member" value="${esc(query)}" oninput="query=this.value;renderMemberList()"><div id="memberlist">${memberList()}</div>${state.role==='Career lead'?btn('+ Assign member',"adding=true;render()",'textbtn'):'<p class="small muted">Member view · switch to Casey in Account to manage assignments.</p>'}`;
if(page==='work')return `<h2>My work</h2><p class="muted">A clear place to start</p><button class="item selected" onclick="go('work')"><strong>Today</strong><small>Focus, notes and next actions</small></button>${btn('Open my position focus',"go('focus')",'item')}${btn('Read my updates',"go('inbox')",'item')}`;
return `<h2>${page==='settings'?'Settings':'Your account'}</h2><p class="muted">Profile and preferences</p>${btn('Profile',"go('account')",'item '+(page==='account'?'selected':''))}${btn('Notification preferences',"go('settings')",'item '+(page==='settings'?'selected':''))}`}
function memberList(){return state.members.map((m,i)=>m.name.toLowerCase().includes(query.toLowerCase())?`<button class="item ${i===memberIndex&&!adding?'selected':''}" onclick="memberIndex=${i};adding=false;render()"><strong>${esc(m.name)}</strong><small>${m.role}　›</small></button>`:'').join('')||'<p>No matching members.</p>'}function renderMemberList(){document.querySelector('#memberlist').innerHTML=memberList()}
const diagram=()=>`<div class="diagram"><div><b>♧</b>People<small>Devotional<br>viewers</small></div><span>→</span><div><b>▤</b>Outcome<small>Find a clear<br>next step</small></div><span>→</span><div><b>♧</b>Contribution<small>Deeper engagement<br>in faith</small></div></div>`;
function focus(){const o=obj();return `<div class="bar"><span class="muted">● ${esc(o.status)} · illustrative draft</span><div class="row">${btn('Save draft','save()','primary')}${btn('Discuss with career lead','requestReview()')}</div></div><div class="editor-layout"><div><label><span>Objective</span><input class="titleinput" aria-label="Objective title" value="${esc(o.title)}" onchange="obj().title=this.value"></label><label><span>Position focus</span><textarea onchange="obj().description=this.value">${esc(o.description)}</textarea></label><div class="section"><h3>Goals</h3><p class="muted small">Keep goals focused and measurable.</p>${o.goals.map((g,i)=>`<div class="goal"><label><span>Goal ${i+1}</span><textarea aria-label="Goal ${i+1}" onchange="obj().goals[${i}].text=this.value">${esc(g.text)}</textarea></label><label><span>Target</span><input value="${esc(g.target)}" onchange="obj().goals[${i}].target=this.value"></label><label><span>When</span><input value="${esc(g.date)}" onchange="obj().goals[${i}].date=this.value"></label><div class="controls">${btn('Remove',`obj().goals.splice(${i},1);render()`,'textbtn danger')}${btn('SMART help',"guidePick('SMART goals')",'textbtn')}</div></div>`).join('')}${btn('⊕ Add goal','addGoal()','textbtn')}</div></div><aside class="aside"><h3>Review timing</h3><p class="muted small">Ask your career lead.</p><div class="hint"><h3>People → Outcome → Contribution</h3>${diagram()}${btn('Objective help',"guidePick('Objectives')",'textbtn')}</div></aside></div><section class="section"><h3>Notes</h3><textarea id="note" placeholder="Add a note, idea or question…" aria-label="New note"></textarea><div class="bar"> <span class="subtle">Only kept in this prototype session.</span>${btn('Add note','addNote()','primary')}</div>${o.notes.map((n,i)=>`<div class="note"><p>${esc(n)}</p>${btn('Delete',`obj().notes.splice(${i},1);render()`,'textbtn small')}</div>`).join('')}</section><section class="section"><h3>Gaps & next steps</h3><textarea aria-label="Gaps and next steps" onchange="obj().gaps=this.value">${esc(o.gaps)}</textarea></section><details class="hint"><summary>Optional development <span class="muted small"> · personal and leadership growth</span></summary><label><span>Personal development</span><textarea onchange="obj().personal=this.value">${esc(o.personal)}</textarea></label><label><span>Leadership development</span><textarea onchange="obj().leadership=this.value">${esc(o.leadership)}</textarea></label>${btn('Save development','save()','primary')}</details><div class="bar section">${btn('View discussion & revisions',"go('review')",'textbtn')}${state.objectives.length>1?btn('Delete objective',"state.objectives.splice(selected,1);selected=0;render()",'textbtn danger'):''}</div>`}
function review(){const o=obj();return `<div class="bar"><span class="badge">${esc(o.status)}</span>${btn('Back to draft',"go('focus')")}</div><h1>Discuss & agree</h1><p class="muted">${esc(o.title)}</p><div class="hint">Review timing: <b>Ask your career lead.</b><br><span class="small">This is a simulated conversation; nothing is sent.</span></div><section class="section"><h3>Discussion</h3>${o.comments.map(c=>`<div class="note"><strong>${esc(c.by)}</strong><p>${esc(c.text)}</p></div>`).join('')||'<p class="muted">Start with what feels clear and what needs refining.</p>'}<textarea id="comment" aria-label="Discussion comment" placeholder="Share a question or suggestion…"></textarea>${btn('Add comment','addComment()','primary')}</section><div class="panel"><h3>Joint agreement</h3><p>Jordan: ${o.memberAgreed?'✓ Agreed':'Pending'}　 ·　Casey: ${o.leadAgreed?'✓ Agreed':'Pending'}</p>${btn(`Agree as ${state.role==='Career lead'?'Casey':'Jordan'}`,'agree()','primary')} ${btn(`Switch to ${state.role==='Career lead'?'Jordan':'Casey'} (demo)`,"state.role=state.role==='Career lead'?'Member':'Career lead';render()")}</div>${o.status==='Agreed'?btn('Start a revision',"obj().status='Draft';obj().memberAgreed=false;obj().leadAgreed=false;go('focus');toast('Revision opened for editing.')") :''}<section class="section"><h3>Saved revisions</h3>${o.revisions.map(r=>`<div class="note">${esc(r.time)} · ${esc(r.status)}<br>${esc(r.title)}</div>`).join('')||'<p class="muted">Save a draft to capture a revision.</p>'}</section>`}
function work(){return `<h1>Good morning, ${state.role==='Career lead'?'Casey':'Jordan'}.</h1><p class="muted">Keep your focus clear. Take the next useful step.</p><div class="steps"><div><span class="stat">${state.objectives.length}</span>Objectives</div><div><span class="stat">${state.objectives.reduce((n,o)=>n+o.goals.length,0)}</span>Goals in focus</div><div><span class="stat">${state.inbox.filter(n=>!n.read).length}</span>Unread updates</div></div><h2>Your next actions</h2><div class="listline"><div><strong>Refine your position focus</strong><br><span class="muted">Connect your objective to a measurable outcome.</span></div>${btn('Continue →',"go('focus')",'primary')}</div><div class="listline"><div><strong>Prepare your discussion</strong><br><span class="muted">Bring open questions to Casey. Ask about review timing.</span></div>${btn('Open discussion',"go('review')")}</div><div class="listline"><div><strong>Need a concrete example?</strong><br><span class="muted">One objective, three goals, on one screen.</span></div>${btn('View example',"guidePick('Example')")}</div><h2 class="section">Quick note</h2><textarea id="note" placeholder="Capture a thought for your selected objective…" aria-label="Quick note"></textarea>${btn('Add to position focus','addNote()','primary')}`}
const milestone=(when,text,why)=>`<div class="milestone"><span class="badge">${when}</span><details><summary>${text}</summary><p>${why}</p></details></div>`;
function guides(){let body='';if(guide==='Example')body=`<div class="example"><div><h3>Critical mission objective</h3><h2>Build and release a clearer next-step screen for one video devotional, using AI to help write code.</h2>${diagram()}</div><div><h3>SMART goals</h3>${milestone('Month 1','Test 20 viewers; count who find the next step.','This establishes a baseline. Record the number who locate the next step without prompting.')}${milestone('Month 3','Release after accessibility and reliability checks.','Define the release checks with the team, then record evidence that they passed.')}${milestone('Month 6','Retest 20 viewers; at least 16 find the next step.','A measurable outcome: 16 out of 20, using the same task and method as the baseline.')}</div></div><div class="example"><div><h3>Personal development · optional</h3><h2>Lead technical design and AI code reviews.</h2></div><div>${milestone('Month 2','Compare 2 build options; recommend one to Product.','Capture the tradeoffs and a clear recommendation.')}${milestone('Month 6','Record 3 AI code reviews and fixes.','Keep brief evidence of the reviews and what improved.')}</div></div><details class="panel"><summary><strong>Gaps / Next step</strong><br><span class="muted">Viewer needs unclear → Confirm with Product.</span></summary><p>Discuss the viewer need before committing to a solution or goal.</p></details><p class="small muted">ⓘ Targets are illustrative. Agree review timing with your career lead.</p>`;
else if(guide==='Objectives')body=`<h2>Say who benefits and what changes.</h2>${diagram()}<div class="panel"><span class="muted small">BEFORE</span><h2>“Improve the devotional.”</h2><span class="small" style="color:#258e70">↓ MAKE THE OUTCOME CLEAR</span><h2 class="section">“Help devotional viewers find a clear next step.”</h2><p>Names the people and the outcome. Connect its contribution to the mission in discussion.</p></div><div class="bar">${btn('Next: SMART goals',"guidePick('SMART goals')",'primary')}${btn('Apply to my objective',"go('focus')")}</div>`;
else if(guide==='SMART goals')body=`<h2>Give your objective evidence and a time frame.</h2><div class="steps"><div><b>1</b>What will you do?<p class="muted">Test the next-step screen.</p></div><div><b>2</b>What will you count?<p class="muted">16 of 20 find the next step.</p></div><div><b>3</b>By when?<p class="muted">Month 6.</p></div></div><div class="panel"><h2>Retest 20 viewers by month 6; at least 16 find the next step.</h2><p><b>Specific</b> task · <b>Measurable</b> result · <b>Achievable</b> with agreed resources · <b>Relevant</b> to the objective · <b>Time-bound</b> checkpoint</p></div>${btn('See the complete example',"guidePick('Example')",'primary')} ${btn('Write my goals',"go('focus')")}`;
else if(guide==='FAQ')body=`${[['When is my review due?','Ask your career lead. This prototype does not assume a schedule.'],['Do I need a personal-development objective?','No. Personal and leadership development are optional.'],['Who agrees my focus?','You and your career lead discuss, refine and jointly agree the focus.'],['Will changes be saved?','Only in memory while this prototype remains open. Reloading or Reset demo clears them.']].map(([q,a])=>`<details class="panel"><summary>${q}</summary><p class="section">${a}</p></details>`).join('')}`;
else body=`<h2>From an idea to an agreed focus.</h2><div class="steps"><div><b>01</b>Capture<p class="muted">Write an outcome and your open questions.</p></div><div><b>02</b>Make concrete<p class="muted">Add a few measurable goals.</p></div><div><b>03</b>Discuss & agree<p class="muted">Refine with your career lead.</p></div></div>${btn('Start with objectives',"guidePick('Objectives')",'primary')}`;
return `<h1>${guide==='Example'?'A position focus in practice':guide}</h1><span class="badge">${guide==='Example'?'Illustrative example':'Practical guidance'}</span><div class="tabs">${['Objectives','SMART goals','Example'].map(t=>btn(t,`guidePick('${t}')`,guide===t?'active':'')).join('')}</div>${body}`}
function inbox(){const n=state.inbox[inboxIndex];return n?`<div class="bar"><span class="badge">${n.read?'Read':'Unread'} · illustrative</span>${btn(n.read?'Mark unread':'Mark read',`state.inbox[inboxIndex].read=!state.inbox[inboxIndex].read;render()`)}</div><h1>${esc(n.title)}</h1><p class="muted">${esc(n.body)}</p><div class="section row">${btn('Open related work →',`go('${n.target}')`,'primary')}${btn('Dismiss','dismiss()')}</div>`:'<div class="empty"><h1>All caught up.</h1><p>Your next actions are in My work.</p>'+btn('Back to My work',"go('work')")+'</div>'}
function department(){if(adding)return `<h1>Assign a registered member</h1><p class="muted">Only registered, unassigned users are available.</p><div class="listline"><div><strong>Taylor Reed</strong><br>Registered · no department</div>${state.members.some(m=>m.name==='Taylor Reed')?'<button disabled>Already assigned</button>':btn('Assign to Engineering','addMember()','primary')}</div><div class="listline">Jordan Morgan · existing member<button disabled>Assigned</button></div><div class="listline">Alex Chen · former member<button disabled>Ineligible</button></div><div class="listline">Sam Lee · Product department<button disabled>Other department</button></div>${btn('Cancel',"adding=false;render()",'section')}`;const m=state.members[memberIndex];return `<h1>${esc(m.name)}</h1><span class="badge">${m.role}</span><div class="panel"><h3>Department membership</h3><p>Engineering</p><p class="muted">${esc(m.email)}</p><p>Career lead: Casey Patel</p></div>${m.name==='Jordan Morgan'?btn('View my position focus',"go('focus')",'primary'):'<p class="muted">Focus content is not shared in this demo.</p>'}${state.role==='Career lead'&&m.role!=='Career lead'?`<div class="section">${btn('Remove department assignment','removeMember()','danger')}</div>`:''}<p class="subtle section">Illustrative permissions. No live accounts or assignments are changed.</p>`}
function account(){return `<div class="account-grid"><h1>${page==='settings'?'Preferences':'Your account'}</h1>${page==='account'?`<label><span>Display name</span><input value="${esc(state.name)}" onchange="state.name=this.value"></label><label><span>Work email (demo)</span><input value="${esc(state.email)}" readonly></label><div class="panel">Engineering · ${state.role}<br>Career lead: Casey Patel</div>${btn('Save profile',"render();toast('Profile saved in memory.')",'primary')}<h2 class="section">Preview a different role</h2><p class="muted">Try member assignment and joint agreement as Casey.</p>${btn(state.role==='Career lead'?'Switch to Jordan · Member':'Switch to Casey · Career lead',"state.role=state.role==='Career lead'?'Member':'Career lead';render();toast('Demo role switched.')")}`:`<label><input type="checkbox" ${state.notifications?'checked':''} onchange="state.notifications=this.checked"> Show in-app notifications</label><p class="muted">Preference only; no emails or real notifications are sent.</p>${btn('Save preferences',"render();toast('Preferences saved in memory.')",'primary')}<div class="hint"><b>Review timing</b><p>Ask your career lead. No schedule is set here.</p></div>`}<div class="section">${btn('Sign out of demo',"state.signed=false;render()")}</div></div>`}
function render(){if(!state.signed){document.querySelector('#app').innerHTML=`<main class="login"><div class="brand"><b>⌂</b>Lantern</div><h1>Welcome back.</h1><p class="muted">Explore the Graphite prototype with a fictional account. No Google setup required.</p>${btn('Continue as Jordan',"state.signed=true;state.role='Member';render()",'primary full')}<p class="small muted section">Prototype only · all changes stay in memory.</p></main>`;return}document.querySelector('#app').innerHTML=`<div class="shell"><aside class="global"><div class="brand"><b>⌂</b>Lantern</div><nav>${navs.map(([p,i,n])=>btn(`<span class="ico">${i}</span>${n}${p==='inbox'&&state.notifications&&state.inbox.some(n=>!n.read)?' <span style="color:#65dbb6">●</span>':''}`,`go('${p}')`,(page===p||(p==='focus'&&page==='review'))?'active':'')).join('')}</nav><div class="foot">09 / Graphite navigator<br>Disposable prototype<br>${btn('Reset demo','reset()')}</div></aside><aside class="master">${masters()}</aside><main class="detail"><header class="topbar">${btn('✉ Inbox',"go('inbox')",'textbtn')}<span class="avatar">${state.role==='Career lead'?'CP':'JM'}</span>${btn(state.role==='Career lead'?'Casey Patel':esc(state.name),"go('account')",'textbtn')}</header><div class="notice">PROTOTYPE · Fictional data · Changes live in memory until reload. ${btn('Reset demo','reset()','textbtn small')}</div><div class="content">${page==='focus'?focus():page==='review'?review():page==='work'?work():page==='guide'?guides():page==='inbox'?inbox():page==='department'?department():account()}</div><details class="state"><summary>Inspect prototype state</summary><pre>${esc(JSON.stringify(state,null,2))}</pre></details></main></div>`}render();
